    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit).
    // We add a penalty for "fragmentation" (small residual space that is hard to fill).
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (unusable space < 10, since min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we reward this placement heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Global state: If we have many open bins, we should be more selective to avoid 
    // keeping too many bins partially filled.
    if !is_new_bin {
        score += (open_bins_count as f64) * 0.5;

        // If this is the last bin that can fit the item, reward using it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    } else {
        // Penalize opening a new bin heavily, scaling by progress.
        // As the stream nears the end, we become slightly more lenient to avoid 
        // suboptimal packing of the final few items.
        score += 60.0 * (1.0 - progress * 0.2);

        // If there are very few open bins, opening a new one is less detrimental.
        if open_bins_count < 2 {
            score -= 15.0;
        }
    }

    // Dynamic balance based on mean residual space.
    // If the average bin is already quite full, we are more willing to start a new one.
    if mean_residual < 20.0 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Core objective: Minimize waste (post_residual).
    // We apply a non-linear penalty to small residuals that are too small to fit future items.
    // As the stream progresses (progress -> 1.0), we become more conservative (packing tighter).

    // Penalize extreme fragmentation: if post_residual is small but > 0, it's often wasted space.
    // We define a "danger zone" for residuals.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 15.0 {
        15.0 - post_res
    } else {
        0.0
    };

    // Lookahead coupling: If the next item cannot fit in this post_residual, apply a penalty.
    // This encourages bins that can accommodate the next item.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Global pressure: If we have many open bins, prioritize filling existing ones deeper.
    // If we have few open bins, we can afford to be more selective.
    let open_bin_pressure = (open_bins_count as f64).sqrt() * 2.0;

    // Interaction term: Combine post_residual with progress to shift from "First Fit" 
    // to "Best Fit" behavior as the stream nears completion.
    let mut score = post_res + (fragmentation_penalty * (1.0 + progress)) + (lookahead_penalty * (1.0 - progress));

    // Special logic for new bin candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is high (bad packing)
        // or if we are forced to (fitting_bins_count is low).
        let new_bin_cost = 25.0 + (mean_residual * 0.5) - (open_bin_pressure);
        score = new_bin_cost;
    } else {
        // Add a slight bias to keep the number of open bins manageable
        score += open_bin_pressure;
    }

    score
}

