    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
