                score -= 40.0;
            }
        } else {
            // Penalty if this choice prevents the next item from fitting in this bin
            score += 15.0;
        }
    }

    // 3. Global state awareness: If we are nearing the end of the stream, 
    // prioritize filling the most empty bins to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Handle the "New Bin" candidate case (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins that are already poorly utilized,
        // or if we have no bins that can fit the current item well.
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 60.0; // Discourage opening new bin unnecessarily
        } else {
            score += 30.0; // Neutral baseline for new bin
        }
    }

    // 5. Prefer bins that are already "half-full" to avoid creating many low-density bins
    if bin_residual < (bin_capacity / 2) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize tightness (Best Fit)
    // We want to minimize post_residual, but heavily penalize opening new bins 
    // early in the stream, while becoming more flexible towards the end.
    let mut score = post * (1.0 + (mean_residual / bin_capacity as f64));

    // Non-linear penalty for opening a new bin
    if bin_residual == bin_capacity {
        // As progress increases, the cost of opening a new bin decreases 
        // to allow for better packing density in the final stages.
        let new_bin_base_penalty = 15.0 * (1.0 - progress).powf(2.0);
        let lookahead_penalty = if next_item_size > 0 && (next_item_size as u32 > bin_capacity - item_size) {
            10.0
        } else {
            0.0
        };
        score = new_bin_base_penalty + lookahead_penalty;
    } else {
        // Reward bins that maintain a residual close to the mean, 
        // discouraging fragmentation of the bin space.
        let fragmentation_penalty = (post - mean_residual).abs() * 0.5;
        score += fragmentation_penalty;

        // If this is the last fitting bin, prioritize it to avoid opening a new one,
        // unless the post_residual is extremely small (creating dead space).
        if fitting_bins_count == 1 {
            score -= 5.0; 
        }
    }

    // Interaction term: penalize small residuals that are too small for common item sizes
    // if we are early in the stream.
    if post < 15.0 && post > 0.0 {
        score += (15.0 - post) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
