    // We keep the base score as post_residual.

    // 2. Penalty for creating "dead space" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are extremely difficult to fill given item sizes 10-100.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic: If the next item fits perfectly into this post_residual,
    // prioritize this bin heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave enough room for the next item to fit
            score -= 10.0;
        } else {
            // Penalize bins that will force an overflow/new bin for the next item
            score += 5.0;
        }
    }

    // 4. Global State Awareness: If this is the only bin that fits the current item,
    // be conservative. If there are many options, be more selective.
    if fitting_bins_count > 1 {
        // If we have many options, we can afford to be pickier (higher penalty for poor fits)
        score += (open_bins_count as f64) * 0.5;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We only want to open a new bin if the current open bins are "too full"
    // to accommodate future items effectively.
    if bin_residual == bin_capacity {
        // High penalty to prevent opening new bins prematurely.
        // We only open a new bin if the average residual of existing bins is already very small.
        score = 85.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals too small to fit typical future items)
    // If post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If current bin fits next item perfectly, prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.5;
    }

    // 3. Global efficiency: If this is a new bin, penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low
        // or if we have very few fitting bins.
        score += 40.0;
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Reward bins that bring the residual closer to the global mean residual (stability).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    // 4. Scarcity heuristic: If this is the last chance to fit the item in existing bins,
    // lower the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression damping: As we near the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}
